files.src/purge.py:
def inactive_accounts(db, months=24):
    return db.query('SELECT id FROM accounts WHERE last_login < now() - interval ? month', months)


def purge(db):
    for account in inactive_accounts(db):
        db.execute('DELETE FROM accounts WHERE id = ?', account)

